<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'; import { useRouter } from 'vue-router'; import { useCart } from '../../stores/cart'; import { useAuth } from '../../stores/auth'; import { http, errorMessage } from '../../api/http'; import type { Order } from '../../types'; import { money } from '../../utils/format'; import FormField from '../../components/FormField.vue'; import LoadingState from '../../components/LoadingState.vue'; import BaseButton from '../../components/BaseButton.vue'
const cart = useCart(), auth = useAuth(), router = useRouter(), busy = ref(false), loading = ref(true), error = ref(''); const form = reactive({ recipientName: auth.user?.fullName || '', recipientPhone: auth.user?.phoneNumber || '', shippingAddress: auth.user?.defaultShippingAddress || '', note: '' });
// Persist exact request until success: reload/network retries reuse the key and payload.
const pending = ref<{ fingerprint: string; payload: Record<string, unknown> } | null>(null); try { pending.value = JSON.parse(sessionStorage.getItem('booknest.checkout') || 'null'); if (pending.value) Object.assign(form, pending.value.payload) } catch { sessionStorage.removeItem('booknest.checkout') }
onMounted(async () => { try { await cart.refresh() } catch (e) { error.value = errorMessage(e) } finally { loading.value = false } });
async function submit() { if (busy.value || !cart.valid) return; busy.value = true; error.value = ''; const items = cart.lines.map(l => ({ ...l })).sort((a,b) => a.productId - b.productId); const content = { recipientName: form.recipientName, recipientPhone: form.recipientPhone, shippingAddress: form.shippingAddress, note: form.note, items }; const fingerprint = JSON.stringify(content); if (pending.value && pending.value.fingerprint !== fingerprint) { error.value = 'Một yêu cầu trước đó chưa được xác nhận. Kiểm tra Đơn hàng của tôi hoặc dùng lại đúng thông tin trước khi thử lại.'; busy.value = false; return } if (!pending.value) { pending.value = { fingerprint, payload: { ...content, idempotencyKey: crypto.randomUUID() } }; sessionStorage.setItem('booknest.checkout', JSON.stringify(pending.value)) } try { const { data } = await http.post<Order>('/orders', pending.value.payload); for (const i of items) cart.remove(i.productId); sessionStorage.removeItem('booknest.checkout'); await router.push(`/orders/${data.id}/payment`) } catch (e) { error.value = errorMessage(e) } finally { busy.value = false } }
</script>
<template><div class="container page"><span class="eyebrow">CHỈ CÒN MỘT BƯỚC NỮA</span><h1>Thông tin đặt hàng</h1><LoadingState v-if="loading" /><p v-if="error" role="alert" class="alert error">{{ error }}</p><p v-if="pending" class="alert">Có yêu cầu chưa xác nhận. Khi thử lại, hệ thống giữ nguyên mã để tránh tạo đơn trùng. <RouterLink to="/orders">Kiểm tra đơn hàng</RouterLink></p><div v-if="!loading" class="checkout-grid"><form id="checkout-form" class="panel" @submit.prevent="submit"><h2>Địa chỉ nhận sách</h2><FormField label="Họ tên người nhận" id="recipient"><input id="recipient" v-model="form.recipientName" required minlength="2" maxlength="120" autocomplete="name"></FormField><FormField label="Số điện thoại" id="phone"><input id="phone" v-model="form.recipientPhone" type="tel" required minlength="8" maxlength="40" autocomplete="tel"></FormField><FormField label="Địa chỉ nhận hàng" id="address"><textarea id="address" v-model="form.shippingAddress" required minlength="10" maxlength="1000" rows="3" autocomplete="street-address"></textarea></FormField><FormField label="Ghi chú (tùy chọn)" id="note"><textarea id="note" v-model="form.note" maxlength="1000" rows="3"></textarea></FormField><p class="muted">Đây là website đồ án. Không có vận chuyển hoặc thanh toán tiền thật.</p></form><aside class="summary-card"><h2>Đơn sách của bạn</h2><div v-for="line in cart.lines" :key="line.productId"><span>{{ cart.products[line.productId]?.name }} × {{ line.quantity }}</span><strong>{{ money((cart.products[line.productId]?.price || 0) * line.quantity) }}</strong></div><div><span>Phí giao hàng</span><span>0đ (giả lập)</span></div><div class="summary-total"><span>Tổng cộng</span><strong>{{ money(cart.total) }}</strong></div><p v-if="!cart.valid" class="alert error">Giỏ trống hoặc sách không khả dụng. <RouterLink to="/cart">Sửa giỏ</RouterLink></p><BaseButton type="submit" form="checkout-form" class="full" :loading="busy" :disabled="!cart.valid">{{ busy ? 'Đang tạo đơn…' : 'Xác nhận đặt hàng' }}</BaseButton><small>Sau bước này bạn được chuyển đến thanh toán giả lập.</small></aside></div></div></template>